"""Compatibility tests for datasets written by Qanary 0.12.3."""

from __future__ import annotations

import json
import os
import shutil
from pathlib import Path
from unittest.mock import patch

import numpy as np
import pytest
import xarray as xr
import zarr

from qanary import measure
from qanary.dataset import convert, load
from qanary.measure import (
    _live_store_root,
    _prune_orphaned_live_stores,
    _target_marker,
)
from qanary.sweep import ZARR_FORMAT, _copy_store

FIXTURES = Path(__file__).resolve().parent / "fixtures" / "qanary-0.12.3"
# Generated by Qimchi's `tests/fixtures/qanary_datasets/make_fixtures.py`.
(FINISHED,) = FIXTURES.glob("*.nc")
(CHECKPOINT,) = FIXTURES.glob("*.zarr")


def _assert_sweep(dataset: xr.Dataset) -> int:
    """Check every measured point and return how many there are."""
    assert dict(dataset.sizes) == {"x": 8, "y": 6}
    np.testing.assert_allclose(dataset["x"], np.linspace(0, 0.7, 8))
    np.testing.assert_allclose(dataset["y"], np.linspace(0, 0.5, 6))
    x, y = np.meshgrid(dataset["x"], dataset["y"], indexing="ij")
    signal = dataset["signal"].values
    measured = np.isfinite(signal)
    np.testing.assert_array_equal(measured, np.isfinite(dataset["current"].values))
    np.testing.assert_allclose(signal[measured], (100 * x + y)[measured])
    np.testing.assert_allclose(
        dataset["current"].values[measured], (x * y - 0.5)[measured]
    )
    count = int(measured.sum())
    # The sweep fills the grid in order, so what was measured is a prefix.
    assert measured.ravel()[:count].all()
    return count


@pytest.fixture
def checkpoint(tmp_path) -> Path:
    """A writable copy of the 0.12.3 checkpoint."""
    copy = tmp_path / CHECKPOINT.name
    shutil.copytree(CHECKPOINT, copy)
    return copy


class TestReading:
    def test_a_finished_measurement_loads(self):
        dataset = load(FINISHED)

        assert _assert_sweep(dataset) == 48
        assert dataset.attrs["Measurement ID"] == FINISHED.stem
        assert dataset["signal"].attrs["unit"] == "A"

    def test_a_checkpoint_loads(self):
        dataset = load(CHECKPOINT)

        assert 0 < _assert_sweep(dataset) < 48
        assert dataset.attrs["Measurement ID"] == CHECKPOINT.stem

    def test_a_checkpoint_converts_to_netcdf(self, checkpoint):
        written = convert(checkpoint.with_suffix(".nc"))

        xr.testing.assert_identical(xr.load_dataset(written), load(CHECKPOINT))


class TestRecovery:
    def test_an_abandoned_checkpoint_is_recovered(self, tmp_path, caplog):
        store = _live_store_root() / CHECKPOINT.name
        shutil.copytree(CHECKPOINT, store)
        target = tmp_path / "data" / FINISHED.name
        _target_marker(store).write_text(str(target), encoding="utf-8")
        os.utime(store, (0, 0))

        with patch.object(measure, "get_live_measurements", return_value=[]):
            _prune_orphaned_live_stores()

        assert not store.exists()
        assert "very likely incomplete" in caplog.text
        xr.testing.assert_identical(xr.load_dataset(target), load(CHECKPOINT))


def _metadata(path: Path) -> dict:
    document = json.loads(path.read_text(encoding="utf-8"))
    for entry in document.get("metadata", {"": document}).values():
        # Zarr 3 also writes the separator that Zarr 2 assumed.
        assert entry.pop("dimension_separator", ".") == "."
    return document


def _files(root: Path) -> set[str]:
    return {p.relative_to(root).as_posix() for p in root.rglob("*") if p.is_file()}


class TestWriting:
    def test_checkpoints_keep_the_layout_older_versions_wrote(self, tmp_path):
        memory: dict = {}
        load(CHECKPOINT).to_zarr(store=memory, mode="w", zarr_format=ZARR_FORMAT)
        written = tmp_path / "new.zarr"
        _copy_store(memory, zarr.storage.LocalStore(written))

        assert _files(written) == _files(CHECKPOINT)
        for name in _files(CHECKPOINT):
            old, new = CHECKPOINT / name, written / name
            if Path(name).name.startswith("."):
                assert _metadata(new) == _metadata(old), name
            else:
                assert new.read_bytes() == old.read_bytes(), name
